using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using Object=UnityEngine.Object;

public static class GridShiftV18Setup {
 public static void Batch(){try{Configure();EditorApplication.Exit(0);}catch(Exception e){Debug.LogException(e);EditorApplication.Exit(1);}}
 public static void Configure(){
  EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");Physics.SyncTransforms();var tags=new SerializedObject(AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/TagManager.asset")[0]);tags.FindProperty("layers").GetArrayElementAtIndex(12).stringValue="FactoryRoof";tags.ApplyModifiedProperties();Directory.CreateDirectory("Assets/Generated/Factory18");Directory.CreateDirectory("Docs/Validacao18");
  var manager=Object.FindFirstObjectByType<DeliveryManager>();var point=manager.points.First(p=>p.name.Contains("Building_Factory"));var factory=Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.name.IndexOf("Factory",StringComparison.OrdinalIgnoreCase)>=0).OrderBy(r=>(r.bounds.center-point.transform.position).sqrMagnitude).First();var cfg=AssetDatabase.LoadAssetAtPath<GridShiftActiveConfig>("Assets/Resources/GridShiftActiveConfig.asset");
  var direction=Vector3.ProjectOnPlane(point.transform.position-factory.bounds.center,Vector3.up).normalized;direction=Mathf.Abs(direction.x)>Mathf.Abs(direction.z)?Vector3.right*Mathf.Sign(direction.x):Vector3.forward*Mathf.Sign(direction.z);var edge=factory.bounds.center+Vector3.Scale(direction,factory.bounds.extents);var side=Vector3.Cross(Vector3.up,direction);bool found=false;
  for(int i=0;i<9&&!found;i++){var candidate=edge+direction*1.8f+side*((i%2==0?1:-1)*((i+1)/2)*1.2f);if(!Physics.Raycast(candidate+Vector3.up*2,Vector3.down,out var floor,20,~((1<<6)|(1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore)||floor.normal.y<.85f)continue;candidate.y=floor.point.y+.03f;if(Physics.CheckCapsule(candidate+Vector3.up*.4f,candidate+Vector3.up*1.5f,.35f,~((1<<6)|(1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore))continue;cfg.depotPosition=candidate;cfg.depotRotation=Quaternion.LookRotation(-direction);found=true;}
  if(!found)throw new Exception("Factory entrance has no accessible pedestrian position.");cfg.factoryPointId=point.id;
  var roads=Object.FindObjectsByType<TrafficRoute>(FindObjectsSortMode.None).Where(r=>r.Valida).ToArray();var shape=cfg.vanPrefab.GetComponent<BoxCollider>();bool parked=false;
  for(float radius=5;radius<=24&&!parked;radius+=1)for(int k=0;k<24&&!parked;k++)foreach(float yaw in new[]{0f,90f,180f,270f}){float angle=k*Mathf.PI/12;var candidate=cfg.depotPosition+new Vector3(Mathf.Cos(angle),0,Mathf.Sin(angle))*radius;if(!Physics.Raycast(candidate+Vector3.up*2,Vector3.down,out var ground,5,~((1<<6)|(1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore)||ground.normal.y<.9f||Mathf.Abs(ground.point.y-(cfg.depotPosition.y-.03f))>.25f)continue;candidate.y=ground.point.y+.1f;var rotation=Quaternion.Euler(0,yaw,0);var ext=shape.size*.78f*.5f;var center=candidate+rotation*(shape.center*.78f);if(Physics.CheckBox(center,ext*.95f,rotation,~((1<<6)|(1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore))continue;bool valid=true;
   foreach(float sx in new[]{-1f,1f})foreach(float sz in new[]{-1f,1f}){var corner=center+rotation*new Vector3(sx*ext.x,0,sz*ext.z);if(!Physics.Raycast(corner+Vector3.up,Vector3.down,out var floor,4,~((1<<6)|(1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore)||floor.normal.y<.9f||Mathf.Abs(floor.point.y-ground.point.y)>.12f){valid=false;break;}foreach(var road in roads)for(int n=1;n<road.pontos.Length;n++){var a=road.pontos[n-1].position;var delta=road.pontos[n].position-a;float t=Mathf.Clamp01(Vector3.Dot(corner-a,delta)/delta.sqrMagnitude);if(Vector3.ProjectOnPlane(corner-a-delta*t,Vector3.up).magnitude<4)valid=false;}}
   if(!valid)continue;var hits=Physics.BoxCastAll(center,ext*.9f,rotation*Vector3.forward,rotation,6,~((1<<6)|(1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore);if(hits.Any(h=>Mathf.Abs(h.normal.y)<.7f&&h.distance<5))continue;cfg.vanPosition=candidate;cfg.vanRotation=rotation;parked=true;break;
  }
  if(!parked)throw new Exception("No supported parking space with a clear exit near Factory.");EditorUtility.SetDirty(cfg);AssetDatabase.SaveAssets();
  var player=Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None).First(p=>p.gameObject.scene.name=="SampleScene");var clone=Object.Instantiate(player.gameObject);clone.name="Factory Player";clone.transform.SetPositionAndRotation(new Vector3(0,.12f,-9),Quaternion.identity);clone.transform.localScale=Vector3.one;var movement=clone.GetComponent<PlayerMovement>();movement.CameraTransform.localPosition=new Vector3(0,1.65f,0);movement.CameraTransform.localRotation=Quaternion.identity;var cc=clone.GetComponent<CharacterController>();cc.height=1.8f;cc.radius=.32f;cc.center=new Vector3(0,.9f,0);var playerAsset=PrefabUtility.SaveAsPrefabAsset(clone,"Assets/Generated/Factory18/FactoryPlayer.prefab");Object.DestroyImmediate(clone);
  string factoryName=factory.name,sourceId=point.id;var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var root=new GameObject("GridShift Factory Interior");var interior=root.AddComponent<GridShiftFactoryInterior>();interior.BuildGeometry();var idlePath="Assets/Generated/Factory18/AttendantIdle.controller";var idle=AssetDatabase.LoadAssetAtPath<UnityEditor.Animations.AnimatorController>(idlePath);if(idle==null){idle=UnityEditor.Animations.AnimatorController.CreateAnimatorControllerAtPath(idlePath);var state=idle.layers[0].stateMachine.AddState("Reception idle");var clips=AssetDatabase.FindAssets("t:AnimationClip").Select(AssetDatabase.GUIDToAssetPath).Where(path=>path.Contains("Hodaart")).SelectMany(path=>AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>());state.motion=clips.FirstOrDefault(c=>c.name.IndexOf("idle",StringComparison.OrdinalIgnoreCase)>=0);idle.layers[0].stateMachine.defaultState=state;}interior.attendantPoint.GetComponent<GridShiftDepotAttendant>().idleController=idle;var insidePlayer=(GameObject)PrefabUtility.InstantiatePrefab(playerAsset);insidePlayer.transform.SetParent(root.transform,true);
  foreach(var material in root.GetComponentsInChildren<Renderer>().Select(r=>r.sharedMaterial).Where(m=>m!=null&&!EditorUtility.IsPersistent(m)).Distinct()){var path="Assets/Generated/Factory18/"+material.name+".mat";var old=AssetDatabase.LoadAssetAtPath<Material>(path);if(old!=null){EditorUtility.CopySerialized(material,old);foreach(var renderer in root.GetComponentsInChildren<Renderer>())if(renderer.sharedMaterial==material)renderer.sharedMaterial=old;}else AssetDatabase.CreateAsset(material,path);}
  RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.3f,.32f,.35f);EditorSceneManager.SaveScene(scene,"Assets/Scenes/FactoryInterior.unity");EditorBuildSettings.scenes=EditorBuildSettings.scenes.Where(s=>!s.path.EndsWith("FactoryInterior.unity")).Concat(new[]{new EditorBuildSettingsScene("Assets/Scenes/FactoryInterior.unity",true)}).ToArray();AssetDatabase.SaveAssets();
  File.WriteAllText("Docs/Validacao18/setup.txt","Factory="+factoryName+"\nEntry="+cfg.depotPosition+"\nParking="+cfg.vanPosition+"\nFactory source point="+sourceId+"\nInterior=24 x 22 m; clear central aisle\n");
 }
}
